"""Standalone report: clean image + separate SVG overlays; works without network or server."""
import html
import json
from pathlib import Path


def render(out,summaries):
    from video_overlays import timeline
    candidates=[]; cards=[]
    for summary in summaries:
        path=out/summary.get('candidates_file','__missing__')
        if path.is_file():
            loaded=json.loads(path.read_text(encoding='utf-8'))
            for c in loaded:
                context=c.get('context_image')
                for frame in c.get('frames',[]):
                    if not frame.get('full_image') and context and context.get('frame')==frame.get('index'):
                        frame['full_image']={k:context[k] for k in ('image','width','height') if k in context}
            candidates.extend(loaded)
        annotated=html.escape(summary['video']); clean=html.escape(summary.get('clean_video',''))
        items=json.loads(path.read_text(encoding='utf-8')) if path.is_file() else []
        overlay=timeline(out/Path(summary['video']).parent,items)
        interactive=bool(overlay and clean)
        player=(f'<div class="motion-video"><video controls preload="metadata" data-annotated="{annotated}" data-clean="{clean}" src="{clean if interactive else annotated}"></video><svg class="motion-video-overlay" aria-label="Spuren und Mindest-Winkelgeschwindigkeit"></svg></div>') if summary['frames'] else '<p>Kein geeignetes Bild verarbeitet.</p>'
        if interactive:
            payload=json.dumps(dict(timeline=overlay,candidates=items),ensure_ascii=False).replace('<','\\u003c')
            player+='<script type="application/json" class="motion-video-data">'+payload+'</script>'
        hint='' if clean else '<p class="muted">Für diesen älteren Lauf zuerst „Zeitreihen / Kataloge aktualisieren“ ausführen, um das unbeschriftete Video zu erzeugen.</p>'
        validation=summary.get('validation')
        if validation:
            hint+=f'<p class="validation-note">Bewegungs-/Formprüfung: {validation["removed_frames"]} zusätzliche verwackelte Bilder und {validation["removed_detections"]} Erkennungen ausgeschlossen. <a href="{html.escape(validation["review"])}">Messbelege und betroffene Originalbilder ansehen</a></p>'
        review=summary.get('review')
        if review:
            hint+=f'<p class="validation-note">Nachprüfung: {html.escape(review["detail"])} <a href="{html.escape(review["url"])}">Korrigierten Lauf und Messbelege öffnen</a></p>'
        cards.append(f'<section><h2>{html.escape(summary["session"])}</h2>{player}{hint}<p>{summary["frames"]} verwendete Bilder · {summary.get("excluded",0)} ausgeschlossen · {summary["hits"]} Trefferbilder · {summary.get("candidate_count",0)} extrahierte Kandidaten</p></section>')
    payload=json.dumps(candidates,ensure_ascii=False).replace('<','\\u003c')
    page='''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AstroAnalyse · Kandidaten-Zeitreihen</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{background:#0c1424;color:#e8effc;font:16px system-ui;margin:0}main{max-width:1250px;margin:auto;padding:30px}h1{font-size:34px}h2{font-size:22px;overflow-wrap:anywhere}p{line-height:1.6}section,article{background:#17243a;border:1px solid #2d405c;border-radius:14px;padding:22px;margin:22px 0}video{width:100%;max-height:680px;background:#050a12}button,input,select{font:inherit}button{padding:9px 14px;background:#285267;color:#fff;border:1px solid #5a829b;border-radius:7px;cursor:pointer}a{color:#70dfd0}.muted{color:#a9bbd4}.toolbar{position:sticky;top:0;z-index:4;background:#15233bf2;border-bottom:1px solid #38506c;padding:14px;display:flex;gap:20px;align-items:center;flex-wrap:wrap}.toolbar label{font-weight:650}.stage{position:relative;background:#040911;margin:16px 0;max-height:680px;overflow:hidden}.stage img{display:block;width:100%;max-height:680px;object-fit:contain}.stage svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.controls input[type=range]{flex:1;min-width:160px}.thumbs{display:flex;gap:8px;overflow-x:auto;margin:16px 0}.thumbs button{padding:5px;min-width:110px;background:#0e1b30}.thumbs img{width:100px;height:68px;object-fit:contain}.thumbs .selected{border:2px solid #69d9c9}.badge{display:inline-block;padding:3px 8px;border-radius:5px;background:#284957;margin:3px}.warn{background:#63412a}.catalog{border-left:3px solid #477289;padding:10px 14px;margin:10px 0;overflow-wrap:anywhere}.catalog h3{margin:0 0 6px;font-size:17px}.empty{border:1px dashed #52718c;padding:25px;border-radius:12px}details{margin:12px 0}pre{white-space:pre-wrap;word-break:break-word}.time{font-variant-numeric:tabular-nums}.legend{max-width:1000px}button:focus-visible,input:focus-visible{outline:3px solid #6de3cf}svg text{paint-order:stroke;stroke:#030710;stroke-width:4px;fill:#fff;font:18px system-ui}
</style></head><body><div class="toolbar"><label><input id="globalOverlay" type="checkbox" checked> Overlays anzeigen</label><span>Ohne Overlay: unbeschriftetes Video und echte Bildausschnitte</span><a href="#candidates">Zu den Kandidaten</a></div><main><h1>AstroAnalyse · Kandidaten im Zeitverlauf</h1><p class="legend muted">Jeder Kandidat wird mit benachbarten Aufnahmen dargestellt. Ausschnitte sind unbeschriftete, gestreckte FITS-Pixel; Markierungen liegen separat darüber. Zeitangaben sind die echten Aufnahmezeiten, nicht die Zeitrafferzeit. Ausgeschlossene verwackelte Kontextbilder sind gekennzeichnet.</p>'''+''.join(cards)+'''<h1 id="candidates">Extrahierte Kandidaten</h1><div id="candidateList"></div><p class="muted">Katalogstatus: „nicht prüfbar“ bedeutet fehlende Voraussetzungen oder Archivdaten. „Kein passender Eintrag“ gilt nur für die tatsächlich geprüfte Datenabdeckung. Geometrisch passende Katalogobjekte sind Hinweise, keine bestätigte Identifikation. CNEOS enthält helle Feuerkugeln, keinen vollständigen Katalog gewöhnlicher Meteore oder Meteoritenfälle. Keine Fotos werden an Katalogdienste übertragen.</p><script id="candidateData" type="application/json">'''+payload+'''</script><script>
const candidates=JSON.parse(document.querySelector('#candidateData').textContent), root=document.querySelector('#candidateList');
const names={meteors:'Meteorflugbahnen · Global Meteor Network',asteroids:'Bekannte Asteroiden · JPL',satellites:'Satelliten · historische Bahnen',aircraft:'Flugzeuge · historische ADS-B-Spuren',fireballs:'Gemeldete Feuerkugeln · CNEOS'};
const states={service_unavailable:'Dienst vorübergehend nicht erreichbar',needs_login:'OpenSky-Anmeldung erforderlich',needs_access:'OpenSky-Archivzugang freischalten',compatible:'Geometrisch vereinbarer Hinweis',checked_no_match:'Geprüft: kein passender Eintrag',not_checkable:'Nicht prüfbar',needs_archive:'Historische Daten fehlen',temporal_hint:'Zeitlicher Hinweis',error:'Abfrage nicht abgeschlossen',disabled:'Abgleich ausgeschaltet'};
const element=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
if(!candidates.length)root.append(element('p',document.querySelector('.validation-note')?'Nach der Bewegungs-/Formprüfung verbleiben in diesem Lauf keine Kandidaten.':'Keine Kandidaten in diesem Lauf. Bei älteren Berichten zuerst die Zeitreihen aktualisieren.','empty'));
candidates.forEach((c,number)=>{
 const card=element('article');card.id='candidate-'+number;card.append(element('h2',c.id+' · '+AstroEvidence.candidateName(c)));card.append(element('p',c.session,'muted'));
 card.append(element('span',c.timestamp_text,'badge time'));card.append(element('span',c.frames.length+' Aufnahmen in der Zeitreihe','badge'));
 if(c.confidence!==null&&c.confidence!==undefined)card.append(element('span','Modellkonfidenz '+Math.round(c.confidence*100)+' %','badge'));
 const toggleLabel=element('label');const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=true;toggle.className='local-overlay';toggleLabel.append(toggle,document.createTextNode(' Overlay für diesen Kandidaten'));card.append(toggleLabel);
 const fullLabel=element('label'),full=document.createElement('input');full.type='checkbox';full.checked=c.frames.some(f=>f.full_image);full.disabled=!full.checked;fullLabel.append(full,document.createTextNode(' Ganzes Bild'));card.append(fullLabel);
 const stage=element('div',undefined,'stage'),img=document.createElement('img'),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');img.alt='Himmelsaufnahme';stage.append(img,svg);card.append(stage);
 const enlarge=element('button','Bild vergrößern ↗');enlarge.onclick=()=>{if(timer){clearInterval(timer);timer=null;play.textContent='Zeitreihe abspielen';}AstroEvidence.openImage(c,index,toggle.checked,full.checked);};stage.style.cursor='zoom-in';stage.onclick=()=>enlarge.onclick();card.append(enlarge);
 const caption=element('p',undefined,'time'),controls=element('div',undefined,'controls');const prev=element('button','◀'),play=element('button','Zeitreihe abspielen'),next=element('button','▶'),slider=document.createElement('input');slider.type='range';slider.min=0;slider.max=c.frames.length-1;slider.value=c.initial_frame;slider.setAttribute('aria-label','Aufnahme der Zeitreihe wählen');controls.append(prev,play,next,slider);card.append(caption,controls);
 const thumbs=element('div',undefined,'thumbs');card.append(thumbs);const original=element('a','Originaldatei öffnen');card.append(original);
 let index=c.initial_frame,timer=null;
 const buttons=c.frames.map((f,i)=>{const b=element('button');const thumb=document.createElement('img');thumb.src=f.image;thumb.alt='Bild '+f.index;thumb.loading='lazy';b.append(thumb,element('div','Bild '+f.index+(f.hit?' · Treffer':'')));b.onclick=()=>show(i);thumbs.append(b);return b;});
 function shape(tag,attrs){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;}
 function show(i){index=(i+c.frames.length)%c.frames.length;const source=c.frames[index],f=AstroEvidence.frameImage(c,source,full.checked);slider.value=index;img.hidden=!f;svg.replaceChildren();caption.textContent=`Bild ${source.index} · ${source.timestamp_text} · ${source.hit?'Kandidat erkannt':'Kontextaufnahme'}${source.excluded?' · verwackelt/ausgeschlossen':''}${!f?' · Vollbild fehlt: Ganzes Bild ausschalten oder Zeitreihe aktualisieren':''}`;original.href=source.original;buttons.forEach((b,j)=>b.classList.toggle('selected',j===index));if(!f)return;img.src=f.url||f.image;svg.setAttribute('viewBox',`0 0 ${f.width} ${f.height}`);svg.style.display=toggle.checked?'':'none';
 if(f.overlay){if(f.overlay.points){const p=f.overlay.points;if(p.length>1)svg.append(shape('polyline',{points:p.map(x=>x.join(',')).join(' '),fill:'none',stroke:'#ffe56e','stroke-width':3}));else svg.append(shape('circle',{cx:p[0][0],cy:p[0][1],r:10,fill:'none',stroke:'#ffe56e','stroke-width':3}));}if(f.overlay.box){const [x,y,w,h]=f.overlay.box;svg.append(shape('rect',{x,y,width:w,height:h,fill:'none',stroke:'#ffe56e','stroke-width':3}));}AstroEvidence.motionLabel(svg,c,f.overlay.points,f.width,f.height);}}
 prev.onclick=()=>show(index-1);next.onclick=()=>show(index+1);slider.oninput=()=>show(Number(slider.value));toggle.onchange=()=>svg.style.display=toggle.checked?'':'none';full.onchange=()=>show(index);
 play.onclick=()=>{if(timer){clearInterval(timer);timer=null;play.textContent='Zeitreihe abspielen';}else{timer=setInterval(()=>show(index+1),650);play.textContent='Pause';}};show(index);
 const information=AstroEvidence.analysisDetails(c,card);
 const site=element('p',c.site?`Standort: ${c.site.name||'gespeicherte Position'} · ${c.site.lat}, ${c.site.lon} · ${c.site.alt_m} m`:'Beobachtungsstandort fehlt. Unter „Standort / Kataloge“ eintragen oder abfragen.','muted');information.append(site);
 for(const result of c.catalogs||[]){const panel=element('div',undefined,'catalog');panel.append(element('h3',names[result.provider]||result.provider));panel.append(element('strong',states[result.status]||result.status));panel.append(element('p',result.detail));if(result.provider==='asteroids'&&result.objects_in_field!==undefined)panel.append(element('p','Objekte im Feld nach JPL-Nachrechnung: '+result.objects_in_field+' · Positionsgrenze 30″ · Grenzgröße '+(result.query?.['vmag-lim']??20)+'.'));for(const match of result.matches||[]){panel.append(element('p',(match.name||match.norad_id||'Eintrag')+' · Abstand '+match.separation_arcsec+'″ · '+match.evidence));}for(const hint of result.temporal_hints||[])panel.append(element('p',hint.name+' · '+hint.evidence));const link=element('a','Datenquelle und Abdeckung');link.href=result.source;link.target='_blank';link.rel='noreferrer';panel.append(link);information.append(panel);}
 const detail=document.createElement('details');detail.append(element('summary','Messdaten und Nachweismethode'));detail.append(element('pre',JSON.stringify({method:c.method,world_path:c.world_path,exposure_seconds:c.exposure_seconds,hit_indices:c.hit_indices,catalogs:c.catalogs},null,2)));information.append(detail);root.append(card);
});
document.querySelectorAll('.motion-video-data').forEach(script=>{const data=JSON.parse(script.textContent),wrapper=script.previousElementSibling,video=wrapper.querySelector('video'),svg=wrapper.querySelector('svg');video._interactiveMotion=true;video._motionDraw=AstroEvidence.videoOverlay(video,svg,data.timeline,data.candidates);video.setAttribute('controlsList','nofullscreen');const full=document.createElement('button');full.textContent='Vollbild';full.className='motion-fullscreen';full.onclick=()=>document.fullscreenElement?document.exitFullscreen():wrapper.requestFullscreen();wrapper.append(full);});
document.querySelector('#globalOverlay').onchange=async e=>{const on=e.target.checked;document.querySelectorAll('.satellite-image-overlay').forEach(svg=>AstroEvidence.setOverlayVisible(svg,on));document.querySelectorAll('.local-overlay').forEach(box=>{box.checked=on;box.dispatchEvent(new Event('change'));});for(const video of document.querySelectorAll('video')){if(video._interactiveMotion){AstroEvidence.setOverlayVisible(video.parentElement.querySelector('svg'),on);video._motionDraw();continue;}const target=on?video.dataset.annotated:video.dataset.clean;if(!target)continue;const paused=video.paused,t=video.currentTime,rate=video.playbackRate;video.addEventListener('loadedmetadata',()=>{video.currentTime=Math.min(t,video.duration||t);video.playbackRate=rate;if(!paused)video.play().catch(()=>{});},{once:true});video.src=target;video.load();}};
</script></main></body></html>'''
    from project_paths import ASSETS
    assets=ASSETS/'static'
    page=page.replace('</style>',(assets/'evidence.css').read_text(encoding='utf-8')+'\n</style>',1)
    page=page.replace('const candidates=JSON.parse',(assets/'evidence.js').read_text(encoding='utf-8')+'\nconst candidates=JSON.parse',1)
    path=out/'bericht.tmp';path.write_text(page,encoding='utf-8');path.replace(out/'bericht.html')
    (out/'kandidaten.json').write_text(json.dumps(candidates,indent=2,ensure_ascii=False),encoding='utf-8')
